-- Every 2+1 bus becomes the 41-seat coach. The test in driver-stops.test.ts keeps this literal
-- equal to createCoachSeatLayout(). Seat numbers on sold tickets are unchanged.
UPDATE "buses"
SET "seat_layout" = '{"layout":"2+1","rows":14,"columns":4,"items":[{"type":"driver","row":0,"column":1},{"type":"seat","seatNo":"1","row":1,"column":1},{"type":"seat","seatNo":"2","row":1,"column":3},{"type":"seat","seatNo":"3","row":1,"column":4},{"type":"seat","seatNo":"4","row":2,"column":1},{"type":"seat","seatNo":"5","row":2,"column":3},{"type":"seat","seatNo":"6","row":2,"column":4},{"type":"seat","seatNo":"7","row":3,"column":1},{"type":"seat","seatNo":"8","row":3,"column":3},{"type":"seat","seatNo":"9","row":3,"column":4},{"type":"seat","seatNo":"10","row":4,"column":1},{"type":"seat","seatNo":"11","row":4,"column":3},{"type":"seat","seatNo":"12","row":4,"column":4},{"type":"seat","seatNo":"13","row":5,"column":1},{"type":"seat","seatNo":"14","row":5,"column":3},{"type":"seat","seatNo":"15","row":5,"column":4},{"type":"seat","seatNo":"16","row":6,"column":1},{"type":"seat","seatNo":"17","row":6,"column":3},{"type":"seat","seatNo":"18","row":6,"column":4},{"type":"seat","seatNo":"19","row":7,"column":1},{"type":"seat","seatNo":"20","row":7,"column":3},{"type":"seat","seatNo":"21","row":7,"column":4},{"type":"seat","seatNo":"22","row":8,"column":1},{"type":"door","row":8,"column":3},{"type":"seat","seatNo":"23","row":9,"column":1},{"type":"seat","seatNo":"24","row":9,"column":3},{"type":"seat","seatNo":"25","row":9,"column":4},{"type":"seat","seatNo":"26","row":10,"column":1},{"type":"seat","seatNo":"27","row":10,"column":3},{"type":"seat","seatNo":"28","row":10,"column":4},{"type":"seat","seatNo":"29","row":11,"column":1},{"type":"seat","seatNo":"30","row":11,"column":3},{"type":"seat","seatNo":"31","row":11,"column":4},{"type":"seat","seatNo":"32","row":12,"column":1},{"type":"seat","seatNo":"33","row":12,"column":3},{"type":"seat","seatNo":"34","row":12,"column":4},{"type":"seat","seatNo":"35","row":13,"column":1},{"type":"seat","seatNo":"36","row":13,"column":3},{"type":"seat","seatNo":"37","row":13,"column":4},{"type":"seat","seatNo":"38","row":14,"column":1},{"type":"seat","seatNo":"40","row":14,"column":3},{"type":"seat","seatNo":"41","row":14,"column":4},{"type":"seat","seatNo":"39","row":14,"column":2}]}'::jsonb,
    "total_seats" = 41
WHERE "seat_layout"->>'layout' = '2+1'
  AND ("total_seats" IS DISTINCT FROM 41 OR "seat_layout"->'items' IS DISTINCT FROM '{"layout":"2+1","rows":14,"columns":4,"items":[{"type":"driver","row":0,"column":1},{"type":"seat","seatNo":"1","row":1,"column":1},{"type":"seat","seatNo":"2","row":1,"column":3},{"type":"seat","seatNo":"3","row":1,"column":4},{"type":"seat","seatNo":"4","row":2,"column":1},{"type":"seat","seatNo":"5","row":2,"column":3},{"type":"seat","seatNo":"6","row":2,"column":4},{"type":"seat","seatNo":"7","row":3,"column":1},{"type":"seat","seatNo":"8","row":3,"column":3},{"type":"seat","seatNo":"9","row":3,"column":4},{"type":"seat","seatNo":"10","row":4,"column":1},{"type":"seat","seatNo":"11","row":4,"column":3},{"type":"seat","seatNo":"12","row":4,"column":4},{"type":"seat","seatNo":"13","row":5,"column":1},{"type":"seat","seatNo":"14","row":5,"column":3},{"type":"seat","seatNo":"15","row":5,"column":4},{"type":"seat","seatNo":"16","row":6,"column":1},{"type":"seat","seatNo":"17","row":6,"column":3},{"type":"seat","seatNo":"18","row":6,"column":4},{"type":"seat","seatNo":"19","row":7,"column":1},{"type":"seat","seatNo":"20","row":7,"column":3},{"type":"seat","seatNo":"21","row":7,"column":4},{"type":"seat","seatNo":"22","row":8,"column":1},{"type":"door","row":8,"column":3},{"type":"seat","seatNo":"23","row":9,"column":1},{"type":"seat","seatNo":"24","row":9,"column":3},{"type":"seat","seatNo":"25","row":9,"column":4},{"type":"seat","seatNo":"26","row":10,"column":1},{"type":"seat","seatNo":"27","row":10,"column":3},{"type":"seat","seatNo":"28","row":10,"column":4},{"type":"seat","seatNo":"29","row":11,"column":1},{"type":"seat","seatNo":"30","row":11,"column":3},{"type":"seat","seatNo":"31","row":11,"column":4},{"type":"seat","seatNo":"32","row":12,"column":1},{"type":"seat","seatNo":"33","row":12,"column":3},{"type":"seat","seatNo":"34","row":12,"column":4},{"type":"seat","seatNo":"35","row":13,"column":1},{"type":"seat","seatNo":"36","row":13,"column":3},{"type":"seat","seatNo":"37","row":13,"column":4},{"type":"seat","seatNo":"38","row":14,"column":1},{"type":"seat","seatNo":"40","row":14,"column":3},{"type":"seat","seatNo":"41","row":14,"column":4},{"type":"seat","seatNo":"39","row":14,"column":2}]}'::jsonb->'items');
--> statement-breakpoint
-- Trips still to run or under way get the seats the old layout did not have, at the trip's price.
INSERT INTO "trip_seats" ("trip_id", "seat_no", "seat_type", "price_minor", "status", "version")
SELECT trip."id", seat_no::text, 'standard', priced."price_minor", 'available', 1
FROM "trips" trip
JOIN "buses" bus ON bus."id" = trip."bus_id"
CROSS JOIN generate_series(1, 41) AS seat_no
JOIN LATERAL (
  SELECT max("price_minor") AS "price_minor" FROM "trip_seats" WHERE "trip_id" = trip."id"
) priced ON priced."price_minor" IS NOT NULL
WHERE bus."seat_layout"->>'layout' = '2+1'
  AND bus."total_seats" = 41
  AND trip."status" NOT IN ('completed', 'cancelled')
ON CONFLICT ("trip_id", "seat_no") DO NOTHING;
